from collections import defaultdict, deque

def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    edges = []
    index = 2
    for _ in range(n - 1):
        x = int(data[index]) - 1
        y = int(data[index + 1]) - 1
        edges.append((x, y))
        index += 2

    return n, k, edges

def find_min_companies(n, k, edges):
    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Find the root of the tree (any node can be root, we choose 0)
    root = 0

    # Calculate the size of each subtree
    size = [1] * n
    def dfs(node, parent):
        for neighbor in graph[node]:
            if neighbor != parent:
                dfs(neighbor, node)
                size[node] += size[neighbor]

    dfs(root, -1)

    # Find the centroid of the tree
    def find_centroid(node, parent, total_size):
        for neighbor in graph[node]:
            if neighbor != parent and size[neighbor] > total_size // 2:
                return find_centroid(neighbor, node, total_size)
        return node

    centroid = find_centroid(root, -1, n)

    # Assign companies to the edges
    companies = [0] * (n - 1)
    company_count = 0

    def assign_companies(node, parent, remaining_k):
        nonlocal company_count
        bad_cities = 0
        for neighbor in graph[node]:
            if neighbor != parent:
                bad_cities += assign_companies(neighbor, node, remaining_k)

        if bad_cities > remaining_k:
            company_count += 1
            bad_cities = 0

        return bad_cities + (size[node] > 1)

    assign_companies(centroid, -1, k)

    # Reassign companies to the edges
    company_count = 0
    company_assignment = {}

    def reassign_companies(node, parent):
        nonlocal company_count
        current_company = company_count + 1
        for neighbor in graph[node]:
            if neighbor != parent:
                if (node, neighbor) not in company_assignment and (neighbor, node) not in company_assignment:
                    company_assignment[(node, neighbor)] = current_company
                    company_assignment[(neighbor, node)] = current_company
                    company_count += 1
                reassign_companies(neighbor, node)

    reassign_companies(centroid, -1)

    # Convert edge assignments to the required format
    result = []
    for u, v in edges:
        if (u, v) in company_assignment:
            result.append(company_assignment[(u, v)])
        else:
            result.append(company_assignment[(v, u)])

    return company_count, result

def main():
    n, k, edges = read_input()
    r, companies = find_min_companies(n, k, edges)
    print(r)
    print(" ".join(map(str, companies)))

if __name__ == "__main__":
    main()
